// The page's ES modules (page/*.mjs) and the lit-html they import, as one classic script:
// page.bundle.js. Opened by double click (file://), Chromium loads no ES module at all, while a
// classic <script src> beside the page still loads; index.html loads this file there and the
// modules themselves from the server. Nothing runs at the page's run time: the bundle is
// committed, and file-bundle.test.mjs fails when it no longer matches the modules.
//
//   node modules/build/file-bundle.mjs      writes page.bundle.js after a change under page/
//
// It understands the import and export forms the page and the vendored lit-html use, and refuses
// the rest rather than guess:
//   import { a, b as c } from './x.mjs'     relative, or '/vendor/...' (core/vendor/)
//   export function f / export const x / export class C / export { a, b as c }
// Each module becomes a function run once, in import order, that returns its exports; an import
// is a copy of the value, so an import cycle, `export let` and `export default` are refused.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO = path.resolve(HERE, '../..');
const VENDOR = path.join(REPO, 'core', 'vendor');
export const ENTRY = path.join(HERE, 'page', 'main.mjs');
export const BUNDLE_FILE = path.join(HERE, 'page.bundle.js');

// Each at the start of a statement (after a line break, ";" or "}"), which it leaves in place.
const IMPORT = /(?<=^|[;\n])()[ \t]*import\s*\{([^}]*)\}\s*from\s*(['"])([^'"\n]+)\3[ \t]*;?/g;
const EXPORT_LIST = /(?<=^|[;\n}])()[ \t]*export\s*\{([^}]*)\}[ \t]*;?/g;
const EXPORT_DECL = /(?<=^|[;\n}])()([ \t]*)export\s+((?:async\s+)?function\s*\*?\s*|const\s+|class\s+)([\w$]+)/g;
const LEFT_OVER = /(^|[;\n}])[ \t]*(import\s*[\w$*{'"]|export\b)/;

// "a, b as c" as [[name in the other module, name here]].
const pairs = (list) => list.split(',').map((s) => s.trim()).filter(Boolean).map((s) => {
  const m = /^([\w$]+)(?:\s+as\s+([\w$]+))?$/.exec(s);
  if (!m) throw new Error(`cannot read "${s}"`);
  return [m[1], m[2] || m[1]];
});

function resolve(from, spec) {
  if (spec.startsWith('/vendor/')) return path.join(VENDOR, spec.slice('/vendor/'.length));
  if (spec.startsWith('./') || spec.startsWith('../')) return path.resolve(path.dirname(from), spec);
  throw new Error(`${from}: cannot bundle the import "${spec}"`);
}

// One module: what it imports, what it exports, and its code without the import and export syntax.
function parse(file) {
  const imports = [];
  const exports = new Map();   // exported name -> name inside the module
  let code = fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
  code = code.replace(IMPORT, (all, pre, list, q, spec) => { imports.push({ file: resolve(file, spec), names: pairs(list) }); return pre; });
  code = code.replace(EXPORT_LIST, (all, pre, list) => { for (const [local, name] of pairs(list)) exports.set(name, local); return pre; });
  code = code.replace(EXPORT_DECL, (all, pre, indent, kind, name) => { exports.set(name, name); return pre + indent + kind + name; });
  const left = LEFT_OVER.exec(code);
  if (left) throw new Error(`${file}: cannot bundle "${code.slice(left.index, left.index + 40).trim()}"`);
  return { file, imports, exports, code };
}

const id = (file) => path.relative(REPO, file).split(path.sep).join('/');

// The modules the entry needs, each after the ones it imports.
function inOrder(entry) {
  const done = new Map();
  const visit = (file, stack) => {
    if (done.has(file)) return;
    if (stack.includes(file)) throw new Error(`import cycle: ${[...stack.slice(stack.indexOf(file)), file].map(id).join(' -> ')}`);
    const mod = parse(file);
    for (const imp of mod.imports) visit(imp.file, [...stack, file]);
    done.set(file, mod);
  };
  visit(path.resolve(entry), []);
  return done;
}

export function bundle(entry = ENTRY) {
  const mods = inOrder(entry);
  const parts = [];
  for (const mod of mods.values()) {
    const take = mod.imports.map((imp) => {
      const from = mods.get(imp.file);
      for (const [name] of imp.names) if (!from.exports.has(name)) throw new Error(`${id(mod.file)}: ${id(imp.file)} does not export "${name}"`);
      return `const { ${imp.names.map(([name, local]) => (name === local ? name : `${name}: ${local}`)).join(', ')} } = $modules[${JSON.stringify(id(imp.file))}];\n`;
    }).join('');
    const give = [...mod.exports].map(([name, local]) => (name === local ? name : `${name}: ${local}`)).join(', ');
    parts.push(`// ---- ${id(mod.file)}\n$modules[${JSON.stringify(id(mod.file))}] = (() => {\n${take}${mod.code.trim()}\nreturn { ${give} };\n})();\n`);
  }
  return `// Generated by modules/build/file-bundle.mjs from ${id(path.resolve(entry))} and what it imports; do not edit.
// The page loads it only when opened as a file (file://), where the browser loads no ES module.
(() => {
'use strict';
const $modules = {};
${parts.join('\n')}})();
`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  fs.writeFileSync(BUNDLE_FILE, bundle());
  console.log(`wrote ${path.relative(process.cwd(), BUNDLE_FILE)}`);
}
